  }}).{
    "newConnection": connection.edges[0].node,
    "masterDataFlowConfig": masterDataFlowConfiguration.edges[0].node
  };

  $returnValue := function($beforeVal,$afterVal) {
    $isNilOrEmpty($afterVal) ? $beforeVal : $afterVal
  };

  $merge(
