data.transform:
(
  /* $state := { "context": $$.state.context }; */
  $CONSTANTS := $state.context.CONSTANTS;
  $PARAMETERS := $CONSTANTS.PARAMETERS;
  $STOP_AFTER_IMPORT := $PARAMETERS.STOP_AFTER_IMPORT;
  $DATA_FLOW_OVERRIDE := $PARAMETERS.DATA_FLOW_OVERRIDE;
  $IGNORE_MODIFIED_AFTER := $PARAMETERS.IGNORE_MODIFIED_AFTER;

  $plexOdbcConfig := $CONSTANTS.masterDataFlowConfiguration;
  $requestedFlow := $plexOdbcConfig.requestedFlow;
  $dataFlowConfig := $plexOdbcConfig.dataFlowConfiguration;

  $DATE_DEFAULTS := {
    "modifiedAfter": $moment("01-01-1970"),
    "modifiedBefore": $moment().add(1,'days').endOf('day')
  };

  $DATE_RANGE_DEFAULTS := {
    "modifiedAfter": {
      "data": {
        "unit": "week",
        "offset": -1,
        "range": 1,
        "base": "startOf"
      },
      "label": "DEFAULTED"
    },
    "modifiedBefore": {
      "data": {},
      "label": "DEFAULTED"
    }
  };

  $getNextFlow := function($requestedFlow) {
    $isNilOrEmpty($DATA_FLOW_OVERRIDE) ? (
      $isNilOrEmpty($requestedFlow.id) ? 
        $dataFlowConfig.flows[0] 
      :
      $findFirstIndex($dataFlowConfig.flows, function($v) {
        $v.id = $requestedFlow.id
      })~>function($index) {
        $dataFlowConfig.flows[$index + 1]
      }
    )
    :
    $dataFlowConfig.flows[id = $DATA_FLOW_OVERRIDE]
  };

  $dateRangeObjectToDate := function($range,$dateType) {
    (
      $IGNORE_MODIFIED_AFTER = true or $isNilOrEmpty($range) ? 
        $lookup($DATE_DEFAULTS,$dateType)
      :
      $range.base = "startOf" ?
        $moment().startOf($range.unit).add($range.offset,$range.unit)
      :
      $range.base = "endOf" ?
        $moment().endOf($range.unit).add($range.offset,$range.unit)
    )
  };

  $applyFilterDefaults := function($filters) {
    (
      $filters := $coalesce([$filters[0], {}]);
      $defaults := [$keys($DATE_RANGE_DEFAULTS)];

      $mergeDeep([
        $filters,
        $defaults.(
          $default := $;
          $curFilterValue := $lookup($filters,$default);
          $isNilOrEmpty($curFilterValue) ? 
            {
              $default: $lookup($DATE_RANGE_DEFAULTS,$default) 
            }
          :
            {
              $default: $curFilterValue
            }
        )
      ])
    )
  };

  $applyModifiedFilter := function($flow) {
    $flow~>| $ | (
      $filters := $applyFilterDefaults(filters);
      {
        "filters": $filters
        ~>| modifiedAfter | {
          "formattedDate": $dateRangeObjectToDate(data,"modifiedAfter")
        }|
        ~>| modifiedBefore | {
          "formattedDate": $dateRangeObjectToDate(data,"modifiedBefore")
        }|
      }
    )|
  };

  $CONSTANTS~>| $.masterDataFlowConfiguration | {},["requestedFlow"] |
  ~>| $.masterDataFlowConfiguration | (
    $nextFlow := $getNextFlow($requestedFlow);
    $nextFlow := $applyModifiedFilter($nextFlow);
    { 
      "requestedFlow": $nextFlow
    }
  ),[] |
)

