(
  /* $PRIOR_FLOW_METRICS := {
    "STARTED_AT": $moment().subtract(5,'minutes').format()
  }; */

  $PRIOR_FLOW_METRICS := $state.context.PRIOR_FLOW_METRICS;
    /* FUNCTIONS */
  $getFlowRunTime := function($startTime, $endTime) {
    (
      $isNilOrEmpty($startTime)~>$not and $not($lowercase($moment($startTime).format()) = "invalid date") ?
      (
        $_start := $coalesce([$parseNumber($moment($startTime).format('x')),0]);
        $_end := $coalesce([$parseNumber($moment($endTime).format('x')),0]);

        ($_end - $_start) * 0.001;
        /* 
        {
          "start": $_start,
          "end": $_end,
          "total": ($_end - $_start) * 0.001
        } 
        */
      )
      :
      0
    )
  };

  $FLOW_STARTED_AT := $moment($PRIOR_FLOW_METRICS.STARTED_AT).format();
  $ENDED_AT := $now();
  $FLOW_RUN_TIME := $getFlowRunTime($FLOW_STARTED_AT,$ENDED_AT);

  $join(
    [
      "Flow ID:",
      $state.context.CONSTANTS.masterDataFlowConfiguration.requestedFlow.dataFlow.name,
      "completed in",
      $string(
        $FLOW_RUN_TIME = "0" ? "unknown" : $FLOW_RUN_TIME
      ),
      "seconds"
    ],
    " "
  );
)

